comp_.source:
sampler sampler_rand00 = sampler_state {
 AddressU = WRAP; 
 AddressV = WRAP;
};

sampler sampler_rand01 = sampler_state {
 AddressU = WRAP; 
 AddressV = WRAP;
};


shader_body
{
        float2x2 rot = { cos(-q2) - 0.01, sin(-q2),
                    -sin(-q2), cos(-q2) - 0.01
              };

    float final_noise = 0;

    ret = tex2D(sampler_rand00, mul(uv-0.5,rot) + 0.5);
    ret += tex2D(sampler_rand01, mul(uv-0.5,rot) + 0.5);

    float2 uv_echo = (uv - 0.5)*1.000*float2(-1,-1) + 0.5;
    float3 output =  tex2D(sampler_main, uv).xyz;
    float3 blur =  tex2D(sampler_main, GetBlur1(uv)).xyz;

    ret *= cross(blur,output);
    ret = pow(ret,0.8);
    ret *= bass+mid+treb; //gamma

ret-=roam_sin.wyx*roam_cos.zwx;
}

per_frame_.source:
decay=0.88;
