warp_.source:
shader_body
{
float2 pixelsize = texsize.zw;
float2 uvm = uv;

float2 noise_uv = uv_orig*texsize.xy*texsize_noise_lq.zw + rand_frame.xy;
float4 noiseVal = tex2D(sampler_noise_lq, noise_uv);

ret.xyz = saturate(tex2D( sampler_pw_main,uvm).xyz*float3(1,1,1) - float3(.0,.0,.0));
ret.xyz = tex2D( sampler_pw_main,uvm).xyz;


float3 rsamp = tex2D(sampler_pw_main,uvm + (noiseVal.xy-.5)*12*pixelsize).xyz;
if (length(ret.xy - uvm) > length(rsamp.xy - uvm)) {
ret.xy = rsamp.xy;
}

rsamp = tex2D(sampler_pw_main,uvm + (noiseVal.zw-.5)*48*pixelsize).xyz;
if (length(ret.xy - uvm) > length(rsamp.xy - uvm)) {
ret.xy = rsamp.xy;
}

ret.z = tex2D(sampler_fw_main,ret.xy).z;

ret.z -= q1*.005;


}

wave_0_per_point.source:
n=sample*6.283;
phs=1.5 * (-sample * 0.2);

tm=q1;// + phs;
tmw=q2;// + phs*8;

flip=flip+1;
flip=flip*below(flip,2);

xp=0;
yp=flip*0.1 + 0.1;//(sin(tm)*0.5 + 0.5)*0.2;
zp=0;

//wrist movement;
ang=sin(tmw*2)*0.5 +0.5;
sinang=sin(ang);cosang=cos(ang);
xq=xp;
yq=yp*sinang + zp*cosang;
zq=yp*cosang - zp*sinang;



ang=tmw + phs*8;//tmw*8;
sinang=sin(ang);cosang=cos(ang);
xp=xq*sinang + yq*cosang;
yp=xq*cosang - yq*sinang;
zp=zq;


phs = phs*8;

//forearm movement;
zp=zp-0.3;
ang=3.14 + sin((tm*2)+phs - 0.5)*1.5;
sinang=sin(ang);cosang=cos(ang);
xq=xp;
yq=yp*sinang + zp*cosang;
zq=yp*cosang - zp*sinang;

//upper arm twist
ang=-1.0 + cos((tm*3.1) + phs + 0.5);
sinang=sin(ang);cosang=cos(ang);
xp=xq*sinang + yq*cosang;
yp=xq*cosang - yq*sinang;
zp=zq;

//upper arm outward;
zp=zp-0.35;
ang=cos(tm*2.3 + phs)*1.75 - 1.05;
sinang=sin(ang);cosang=cos(ang);
xq=xp*sinang + zp*cosang;
yq=yp;
zq=xp*cosang - zp*sinang;

//upper arm up down;
ang=cos(tm+phs)*0.5 - 0.5;
sinang=sin(ang);cosang=cos(ang);
xp=xq;
yp=yq*cosang - zq*sinang;
zp=yq*sinang + zq*cosang;

//xp=xq;yp=yq;zp=zq;


//project into screenspace and draw on screen
zp=zp+2;
xs=xp/zp;
ys=yp/zp;

x=xs+0.5;
y=ys*1.3+0.5;


a=(1-sample);

b=b+pow(1-sample,2)*0.3;



r1=t1;
g1=t2;
b1=t3;
r2=t4;
g2=t5;
b2=t6;

r=r1*flip + r2*(1-flip);
g=g1*flip + g2*(1-flip);
b=b1*flip + b2*(1-flip);

